{
  "name": "@javargasm/opencode-kiro-auth",
  "version": "8.3.2",
  "description": "Kiro provider plugin for OpenCode: AWS Builder ID / Identity Center login and Anthropic-compatible local gateway for CodeWhisperer streaming.",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/javargasm/opencode-kiro-auth.git"
  },
  "homepage": "https://github.com/javargasm/opencode-kiro-auth#readme",
  "bugs": {
    "url": "https://github.com/javargasm/opencode-kiro-auth/issues"
  },
  "keywords": [
    "opencode-package",
    "opencode",
    "plugin",
    "provider",
    "kiro",
    "aws",
    "codewhisperer",
    "amazon-q",
    "claude"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "opencode-kiro-mcp": "./dist/mcp/index.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.js"
    },
    "./mcp": {
      "types": "./dist/mcp/index.d.ts",
      "default": "./dist/mcp/index.js"
    }
  },
  "oc-plugin": [
    "server",
    "tui"
  ],
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "clean": "rm -rf dist",
    "build:js": "bun build src/index.ts src/mcp/index.ts --outdir dist --target node --format esm --external '@opencode-ai/*'",
    "build:tui": "bun ./build-tui.ts",
    "build:types": "tsc -p tsconfig.build.json",
    "build": "bun run clean && bun run build:js && bun run build:tui && bun run build:types",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:bun": "bun test test/gateway.test.ts",
    "test:artifact": "bun run build && bun test ./test/tui-artifact.bun.ts",
    "test:watch": "vitest",
    "check": "bun run typecheck && bun run test && bun run test:bun && bun run test:artifact",
    "changeset": "changeset",
    "version": "changeset version",
    "prepack": "bun run build",
    "prepublishOnly": "bun run check"
  },
  "devDependencies": {
    "@changesets/changelog-github": "^0.5.0",
    "@changesets/cli": "^2.27.0",
    "@opencode-ai/plugin": "^1.17.3",
    "@types/bun": "latest",
    "typescript": "^5.0.0",
    "vitest": "^4.1.9"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "dependencies": {
    "@opentui/core": "^0.3.4",
    "@opentui/keymap": "^0.3.4",
    "@opentui/solid": "^0.3.4",
    "solid-js": "1.9.12"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "engines": {
    "bun": ">=1.1.0"
  }
}
